<!--
 * 聚合批次管理页面
 *
 * <p>消息聚合批次管理，支持分页查询聚合批次、刷新指定批次、刷新所有到期批次。
 *
 * @path apps/message-web/src/views/aggregate/index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 聚合批次管理（列表页）
 * <p>消费后端契约 AggregateController（src/api/aggregate.ts，auto-generated by bash/gen-contract.py）：
 * page() 分页查询聚合批次；行操作「刷新批次」调 flushByGroup({group, receiver})；
 * 工具栏「刷新所有到期批次」调 flushDue()。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page } from '@ydsz/common-ui';

import { h } from 'vue';

import { YdBadge, YdButtonBase } from '@ydsz-core/ydsz-ui';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { flushByGroup, flushDue, page } from '#/api/aggregate';
import type { MsgAggregateVO } from '#/api/models';

defineOptions({ name: 'AggregateManagement' });

/** 状态列 Tag 类型映射 */
function mapTagVariant(type: 'success' | 'danger' | 'warning' | 'info'): 'default' | 'destructive' | 'outline' | 'secondary' {
  if (type === 'danger') return 'destructive';
  if (type === 'warning') return 'outline';
  if (type === 'info') return 'secondary';
  return 'default';
}

function getStatusType(status?: string): 'success' | 'danger' | 'warning' | 'info' {
  const upper = (status ?? '').toUpperCase();
  if (['SENT', 'ACTIVE'].includes(upper)) return 'success';
  if (['FAILED', 'ERROR'].includes(upper)) return 'danger';
  if (['PENDING', 'SENDING', 'EXPIRED'].includes(upper)) return 'warning';
  return 'info';
}

const gridOptions: VxeTableGridOptions<MsgAggregateVO> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'id', title: '批次ID', width: 220 },
    { field: 'aggregateGroup', title: '聚合组', width: 160 },
    { field: 'receiver', title: '接收人', width: 140 },
    { field: 'channel', title: '通道', width: 100 },
    { field: 'messageCount', title: '消息数量', width: 100 },
    {
      field: 'batchStatus',
      title: '批次状态',
      width: 110,
      slots: {
        default: ({ row }) =>
          h(YdBadge, { variant: mapTagVariant(getStatusType(row.batchStatus)) }, () => row.batchStatus ?? '-'),
      },
    },
    {
      field: 'status',
      title: '状态',
      width: 100,
      slots: {
        default: ({ row }) =>
          h(YdBadge, { variant: mapTagVariant(getStatusType(row.status)) }, () => row.status ?? '-'),
      },
    },
    { field: 'scheduledSendAt', title: '计划发送时间', width: 170 },
    { field: 'createdAt', title: '创建时间', width: 170 },
    {
      field: 'action',
      title: '操作',
      width: 110,
      fixed: 'right',
      slots: {
        default: ({ row }) =>
          h(
            YdButtonBase,
            { size: 'sm', variant: 'link', onClick: () => handleFlushByGroup(row) },
            () => '刷新批次',
          ),
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async (_page, formValues) => {
        const res = await page({ query: { ...formValues } });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: {
    enabled: true,
    items: [
      {
        field: 'status',
        title: '状态',
        itemRender: { name: 'YdInput', props: { placeholder: '状态' } },
      },
      {
        field: 'receiver',
        title: '接收人',
        itemRender: { name: 'YdInput', props: { placeholder: '接收人' } },
      },
      {
        field: 'channel',
        title: '通道',
        itemRender: { name: 'YdInput', props: { placeholder: '通道' } },
      },
    ],
  },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });

/** 刷新指定批次 */
async function handleFlushByGroup(row: MsgAggregateVO) {
  if (!row.aggregateGroup) return;
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await YdConfirm(
      `确定刷新聚合组「${row.aggregateGroup}」的批次吗？`,
      '刷新确认',
      { type: 'warning' },
    );
  } catch {
    return; // 用户主动取消操作
  }
  // 步骤2：执行刷新 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    const count = await flushByGroup({ group: row.aggregateGroup, receiver: row.receiver });
    showToast.success(`刷新完成，共刷新 ${count} 条记录`);
    gridApi.query();
  } catch {
    // 错误已由请求拦截器展示，无需重复处理
  }
}

/** 刷新所有到期批次 */
async function handleFlushDue() {
  // 步骤1：确认弹窗（用户取消直接返回）
  try {
    await YdConfirm('确定刷新所有到期的聚合批次吗？', { title: '刷新确认', type: 'warning', });
  } catch {
    return; // 用户主动取消操作
  }
  // 步骤2：执行刷新 API（失败提示由 errorMessageResponseInterceptor 统一处理）
  try {
    const count = await flushDue();
    showToast.success(`刷新完成，共刷新 ${count} 条到期批次`);
    gridApi.query();
  } catch {
    // 错误已由请求拦截器展示，无需重复处理
  }
}
</script>
<template>
  <Page auto-content-height>
    <Grid table-title="聚合批次">
      <template #toolbar-tools>
        <YdButtonBase variant="destructive" @click="handleFlushDue">刷新所有到期批次</YdButtonBase>
      </template>
    </Grid>
  </Page>
</template>
